from PIL import Image
def dimensions(m):
 t=m.group(0)
 if 'width='in t:return t
 src=re.search(r'src="([^"]+)"',t)
 if src and not src.group(1).startswith('http'):
  im=Image.open(D/src.group(1).lstrip('/'));return t[:-1]+f' width="{im.width}" height="{im.height}">'
 return t
